//! Real signed qualification credentials, generated by the shared auth fixture.
use acyclic_agent_host_conformance::{Result as SuiteResult, protocol::Endpoint};
use acyclic_harness_core::{agent::AgentPath, conversation::FileRef};
use acyclic_stream::{BoxProviderFuture, StreamProvider};
use std::sync::Arc;
use wasm_bindgen::JsCast as _;
use wasm_bindgen::prelude::*;

#[wasm_bindgen(js_name = hostFixtureModelEvents)]
pub fn events(step: u32) -> Result<JsValue, JsValue> {
    to_value(&acyclic_agent_host_conformance::protocol::model_events(
        step,
    ))
    .map_err(|error| JsValue::from_str(&error.to_string()))
}

#[wasm_bindgen(js_name = hostFixtureTool)]
pub fn tool() -> Result<JsValue, JsValue> {
    to_value(&acyclic_agent_host_conformance::protocol::tool_definition())
        .map_err(|error| JsValue::from_str(&error.to_string()))
}

struct Hosted {
    port: JsValue,
    binding: Vec<u8>,
    provider: Arc<dyn StreamProvider>,
}

async fn invoke(port: &JsValue, method: &str, args: &[JsValue]) -> SuiteResult<JsValue> {
    let function = js_sys::Reflect::get(port, &method.into())
        .map_err(|error| format!("hosted {method}: {error:?}"))?
        .dyn_into::<js_sys::Function>()
        .map_err(|_| format!("hosted {method} is not callable"))?;
    let array: js_sys::Array = args.iter().collect();
    let pending = function
        .apply(port, &array)
        .map_err(|error| format!("hosted {method}: {error:?}"))?;
    wasm_bindgen_futures::JsFuture::from(js_sys::Promise::resolve(&pending))
        .await
        .map_err(|error| format!("hosted {method}: {error:?}").into())
}

pub async fn open(
    factory: &js_sys::Function,
    policy: acyclic_harness_core::approvals::ApprovalPolicy,
) -> SuiteResult<Box<dyn Endpoint>> {
    let policy = to_value(&policy)?;
    let pending = factory
        .call1(&JsValue::UNDEFINED, &policy)
        .map_err(|error| format!("hosted factory: {error:?}"))?;
    let port = wasm_bindgen_futures::JsFuture::from(js_sys::Promise::resolve(&pending))
        .await
        .map_err(|error| format!("hosted factory: {error:?}"))?;
    let binding = invoke(&port, "binding", &[]).await?;
    let provider = invoke(&port, "provider", &[]).await?;
    let provider = acyclic_stream::WasmStream::connect_provider(provider)
        .map_err(|error| format!("hosted storage: {error:?}"))?
        .provider();
    Ok(Box::new(Hosted {
        port,
        binding: js_sys::Uint8Array::new(&binding).to_vec(),
        provider,
    }))
}

impl Endpoint for Hosted {
    fn binding(&self) -> &[u8] {
        &self.binding
    }
    fn provider(&self) -> Arc<dyn StreamProvider> {
        self.provider.clone()
    }
    fn exchange(
        &self,
        invocation: bytes::Bytes,
    ) -> BoxProviderFuture<'_, SuiteResult<bytes::Bytes>> {
        Box::pin(async move {
            let reply = invoke(
                &self.port,
                "call",
                &[js_sys::Uint8Array::from(invocation.as_ref()).into()],
            )
            .await?;
            Ok(js_sys::Uint8Array::new(&reply).to_vec().into())
        })
    }
    fn drain<'a>(&'a self, agent: &'a AgentPath) -> BoxProviderFuture<'a, SuiteResult> {
        Box::pin(async move {
            invoke(&self.port, "drain", &[agent.to_string().into()]).await?;
            Ok(())
        })
    }
    fn read_file<'a>(
        &'a self,
        agent: &'a AgentPath,
        file: &'a FileRef,
    ) -> BoxProviderFuture<'a, SuiteResult<Vec<u8>>> {
        Box::pin(async move {
            let reply = invoke(
                &self.port,
                "readFile",
                &[agent.to_string().into(), to_value(file)?],
            )
            .await?;
            Ok(js_sys::Uint8Array::new(&reply).to_vec())
        })
    }
    fn effects(&self) -> BoxProviderFuture<'_, SuiteResult<u64>> {
        Box::pin(async move {
            serde_wasm_bindgen::from_value(invoke(&self.port, "effects", &[]).await?)
                .map_err(Into::into)
        })
    }
}

#[wasm_bindgen(js_name = hostFixtureGrants)]
pub fn grants() -> Result<JsValue, JsValue> {
    let grant =
        acyclic_fs::access::Capability::whole_volume(None, &acyclic_fs::access::Action::ALL)
            .to_scope_label()
            .map_err(|error| JsValue::from_str(&error.to_string()))?;
    Ok(js_sys::Array::of2(
        &JsValue::from_str(acyclic_harness_core::contract::capability::INTERACTION_ROUTE),
        &JsValue::from_str(&grant),
    )
    .into())
}

#[wasm_bindgen(js_name = hostFixtureTrust)]
pub fn trust() -> String {
    let keys = acyclic_auth::testing::Snapshot::default();
    serde_json::json!({
        "environment": "test", "environment_keys": keys.environments,
        "account": "account", "issuer_keys": keys.issuers, "minimum_key_epoch": 1,
        "revoked_key_ids": [], "revoked_block_ids": [],
    })
    .to_string()
}

#[wasm_bindgen(js_name = hostFixtureCredential)]
pub fn credential() -> Vec<u8> {
    use acyclic_auth::contract::*;
    use acyclic_stream::UnixMillisClock as _;
    let now = acyclic_stream::SystemUnixMillisClock.now_unix_millis() / 1000;
    acyclic_auth::testing::root(|block| {
        if let Some(key) = block
            .certificates
            .as_mut()
            .and_then(|chain| chain.keys.first_mut())
        {
            key.key.validity = Validity {
                not_before_unix_seconds: now.saturating_sub(1),
                expires_at_unix_seconds: now + 3600,
            };
            key.key.principal.id = "human".into();
            key.key.grants = GrantSet {
                grants: vec![Grant {
                    kind: GrantKind::Resource(ResourceGrant {
                        resource: ResourcePattern {
                            name: "actors:/agents".into(),
                            prefix: false,
                        },
                        actions: vec!["actors/invoke".into()],
                    }),
                }],
            };
        }
    })
}

fn to_value(value: &impl serde::Serialize) -> Result<JsValue, serde_wasm_bindgen::Error> {
    value.serialize(
        &serde_wasm_bindgen::Serializer::new()
            .serialize_maps_as_objects(true)
            .serialize_large_number_types_as_bigints(true)
            .serialize_missing_as_null(true),
    )
}

/// Capture adoption and exact volume grants from an actual production spawn.
#[wasm_bindgen(js_name = spawnAdoptionFixture)]
pub async fn spawned(factory: js_sys::Function) -> Result<JsValue, JsValue> {
    use acyclic_agent_host_conformance::protocol;
    use acyclic_harness_client::{AgentCommand, AgentReply};
    use acyclic_harness_core::{
        agent::{AgentRecord as _, InboxRecord, IntentId},
        approvals::ApprovalPolicy,
        conversation::VolumeOperation,
        model::ModelContent,
    };
    use futures::TryStreamExt as _;
    let result: SuiteResult<JsValue> = async {
        let endpoint = open(&factory, ApprovalPolicy::accept_all("conformance")).await?;
        let AgentReply::Root { agent: root } =
            protocol::call(endpoint.as_ref(), &AgentCommand::Root).await??
        else {
            return Err("fixture Root reply differs".into());
        };
        let AgentReply::Spawned { agent: child, .. } = protocol::call(
            endpoint.as_ref(),
            &AgentCommand::Spawn {
                parent: root,
                id: IntentId::try_from("adoption-fixture")?,
                brief: ModelContent::Text("Respond after explicit adoption".into()),
            },
        )
        .await??
        else {
            return Err("fixture Spawn reply differs".into());
        };
        let inbox: Vec<acyclic_stream::Record> = endpoint
            .provider()
            .read(acyclic_stream::ReadRequest {
                path: child.inbox()?,
                from: 0,
                limit: 64,
            })
            .await?
            .try_collect()
            .await?;
        let adopted = InboxRecord::decode(&inbox.last().ok_or("fixture adoption missing")?.value)?;
        let InboxRecord::ForkAdopted(adopted) = adopted else {
            return Err("fixture adoption differs".into());
        };
        let private = adopted
            .volumes
            .iter()
            .find(|binding| binding.name == "private")
            .ok_or("fixture private volume missing")?;
        let grants = vec![
            acyclic_harness_core::contract::capability::INTERACTION_ROUTE.to_owned(),
            private
                .volume
                .capability(VolumeOperation::Read, &mut None)?,
            private
                .volume
                .capability(VolumeOperation::Write, &mut None)?,
        ];
        to_value(&serde_json::json!({"child": child, "grants": grants})).map_err(Into::into)
    }
    .await;
    result.map_err(|error| JsValue::from_str(&format!(
        "STEP adoption-fixture spawn failed: {error}; recovery: bash scripts/qualify-cloudflare.sh")))
}
